import glob,re,csv,datetime as dt
def parse(path):
    d={}
    for l in open(path,errors='ignore'):
        m=re.search(r'(\d{4}-\d{2}-\d{2})\D+?(\d\.\d{3})\b',l)
        if m: d[m.group(1)]=m.group(2); continue
        m=re.search(r'(\d{1,2})/(\d{1,2})/(\d{4})\D+?(\d\.\d{3})\b',l)
        if m: d['%s-%02d-%02d'%(m.group(3),int(m.group(1)),int(m.group(2)))]=m.group(4)
    return d

